{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name callee, c.span_name, c.attr_span_kind k, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95_ms, round(avg(c.duration)/1e6,1) avg_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-basic-service' AND p.attr_span_kind='Client' AND p.span_name='GET' GROUP BY 1,2,3 ORDER BY 4 DESC", "claim": "Basic's outgoing GET calls take seconds at the client (p95 4.8s), but the callee server spans answer in 9-40ms."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, attr_k8s_pod_name pod, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND attr_span_kind='Client' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, attr_k8s_pod_name, span_name, count(*), round(quantile_cont(duration,0.95)/1e6,1), round(avg(duration)/1e6,1) FROM normal_traces WHERE service_name='ts-basic-service' AND attr_span_kind='Client' GROUP BY 1,2,3,4 ORDER BY 1,3,4", "claim": "Only basic's GET client spans slowed (p95 46ms to 4830ms); its POST client spans stayed near normal (63ms to 72ms)."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name='ts-basic-service' GROUP BY 1,2 ORDER BY 2", "claim": "Basic's own server span POST /basic/travel p95 rose to about 10.8s from 278ms, with fewer requests.", "_note": "see claim"},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, round(avg(value),2) avg_v, round(max(value),2) max_v, count(*) n FROM abnormal_metrics_sum WHERE metric = 'hubble_http_request_duration_p95_seconds' AND attr_source ILIKE '%basic%' GROUP BY 1,2,3", "claim": "Hubble HTTP p95 duration on basic-service traffic rose to about 3s average and 10s max; basic CPU and memory stayed flat."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-basic-service", "to": "ts-travel-service",
     "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name IN ('ts-route-plan-service','ts-travel-service','ts-travel2-service','ts-preserve-service') GROUP BY 1,2,3 ORDER BY 4 DESC", "claim": "Travel's server span for trip_detail is slowed to about 10s; travel calls basic and is slowed in turn."}]},
    {"from": "ts-basic-service", "to": "ts-travel2-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name callee, c.span_name, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel2-service' AND p.attr_span_kind='Client' AND p.span_name LIKE 'GET%' GROUP BY 1,2 ORDER BY 3 DESC", "claim": "Travel2 calls to basic slowed from 476ms to 9.7s p95; the travel2 trip_detail path is slowed by basic."}]},
    {"from": "ts-basic-service", "to": "ts-preserve-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, attr_span_kind k, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-preserve-service','ts-basic-service') GROUP BY 1,2 ORDER BY 1,2", "claim": "Preserve's server p95 rose to about 21s while its calls to basic rose to about 9.9s; other preserve callees stayed fast."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name IN ('ts-route-plan-service','ts-travel-service') GROUP BY 1,2,3 ORDER BY 4 DESC", "claim": "Route-plan's calls into travel's trips/left and trip_detail endpoints are slowed, with route-plan's own time flat."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name='ts-travel2-service' GROUP BY 1,2,3 ORDER BY 4 DESC", "claim": "Route-plan's calls into travel2's trip_detail and trips/left endpoints are slowed to 0.4s to 13s p95."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2,3 ORDER BY 4 DESC", "claim": "Travel-plan's calls to route-plan's routePlan endpoints now take 0.7s to 27.6s p95."}]}
  ]
}
